/* Garten › Regeln › Reise & Jahreszeiten, Teil B: Dunkelheit, Schwerer Stress, Jahreszeiten (Vol. II S.254–275) */
(function(){
var K = "garten/regeln/reise", L = (HH_TEXT[K] = HH_TEXT[K] || []);
function bild(n, w){ return {t: "bild", s: "garten-" + n, w: w}; }
function B(h, b){ return {t: "box", h: h, b: b}; }
function Q(h, t){ return {t: "box", h: h, b: [t]}; }

L.push(
{id: "dunkelheit", t: "Dunkelheit", p: 254, b: [
 "Als wäre das Reisen durch den Garten bei hochstehender Sonne nicht schwer genug, muss man manchmal im Dunkeln auf Abenteuer gehen.",
 {t: "h", x: "Dämmerlicht"},
 "Bist du an einem extrem dunklen Ort, aber nicht in völliger Finsternis, herrscht Dämmerlicht. Zum Beispiel, wenn du durch die Tunnel des Underground stolperst, nur mit ein paar verstreuten Lichtstrahlen, oder nachts unter einem sternenübersäten Himmel reist. Bei Dämmerlicht erleidest du -1 auf alle Würfe, die auf Sicht beruhen, auch auf Würfe zum Schießen oder zum Entdecken versteckter Feinde. Gleichzeitig erhältst du +1 auf alle Würfe zum Verstecken oder zum lautlosen Bewegen und auf alle Würfe, um Kugeln eines Littlings zu vermeiden oder ihnen auszuweichen.",
 {t: "h", x: "Völlige Dunkelheit"},
 "Du bist von tiefster, dunkelster Schwärze umgeben und siehst nicht einmal einen Fuß vor deiner Nase. Zum Beispiel, wenn du nachts in den Tiefen des Underwood reist, wo der Himmel völlig von Ästen verdeckt ist, oder dich tief im Underground verirrst, wo nur Maulwürfe und Tausendfüßler leben. Bei völliger Dunkelheit kannst du nur noch blind vorwärtstasten, ohne zu sehen, wohin du trittst. Du scheiterst automatisch bei allen Würfen, die auf Sicht beruhen, und bei allen Würfen zum Schießen auf mehr als Kurze Distanz. Außerdem erleidest du -3 auf alle Würfe, um dich zu orientieren, nicht in eine Falle oder einen Hinterhalt zu tappen oder auf Kurze Distanz zu schießen. Gleichzeitig erhältst du dieselben Vorteile wie bei Dämmerlicht, und andere Littlings können dich nicht finden oder mit Fernwaffen treffen, solange du deine Position nicht durch lauten Lärm verrätst.",
 {t: "h", x: "Lichtquellen"},
 "Mit einer Lichtquelle wie einer Fackel, einer Laterne oder einem glitzernden Klumpen kannst du in Reichweite Licht durch Dämmerlicht und völlige Dunkelheit werfen. So vermeidest du die Abzüge der Dunkelheit, verrätst aber unweigerlich deine Position allen in Sichtweite. Bedenke, dass Salamander ihre Gliedmaßen leuchten lassen können und deshalb auf Wunsch jederzeit Licht in die Dunkelheit werfen können. Reist du mit einer Motte, kann es außerdem äußerst schwer sein, sie von Lichtquellen in der Dunkelheit fernzuhalten. Gleichzeitig könntest du, sind Motten in der Nähe, unbeabsichtigt ihre Aufmerksamkeit erregen.",
 {t: "box", h: "Im Dunkeln sehen", b: ["Einige seltene Littlings, die den Pitchblack-Vertrag geschlossen oder die Gunst der Schleiereule erhalten haben, sehen im Dunkeln wie am hellen Tag. Diese Glücklichen erhalten alle Vorteile der Dunkelheit, ohne die Nachteile zu erleiden. Auch manche Tiere wie Maulwürfe, Motten und bestimmte Vögel sehen im Dunkeln und bewegen sich mit ihren anderen Sinnen durch die Finsternis. Schließlich kann ein Jäger dank des Manövers Auge des Jägers seine Augen schnell anpassen, um die Wirkung der Dunkelheit zu mildern."]},
 {t: "box", h: "Der Schatten, die Finsternis, die Nacht", b: [
  "Der Schatten, die Finsternis, die Nacht. Manche behaupten, es seien nur verschiedene Namen derselben Macht. Drei Gesichter derselben schwarzen Münze. Wenn die Brambles ihre dunkle Silhouette auf den Garten werfen, sagen die Barghests: „Geh nicht im Schatten, dort lauern Spinnen.“ Und wenn Gnomes im Underground die Augen öffnen und nichts als Schwärze sehen, flüstern sie: „Sie ist da, die Finsternis.“ Dann geht die Sonne unter, und bevor die anderen Sterne aufgehen, heben die Fae den Blick zum onyxfarbenen Himmel und seufzen unruhig: „Die Nacht ist gekommen.“",
  "Jedes Mal senken diese Littlings die Stimme, um die Düsternis nicht zu stören, aus Furcht vor dieser Macht mit den vielen Namen. Jener düsteren, stillen Macht, die sich überallhin erstreckt und dem Tag mit knochigen Fingern das Licht stiehlt, einer schwarzen Schlange gleich, die jede Form und Farbe verschluckt. Ja. Der Schatten, die Finsternis und die Nacht könnten drei Namen derselben Macht sein. Doch manche glauben anderes.",
  "Manche sagen, der Schatten sei eine listige, launische Macht, die sich innerhalb und außerhalb des House windet wie ein kopfloser Tausendfüßler. Alles, wonach der Schatten verlangt, ist, sich dem Licht entgegenzustellen. Je heller das Licht, desto länger, größer und fester wird der Schatten und holt sich mit leiser Stimme zurück, was Sonne und Flamme gestohlen haben. Doch was der Schatten fürchtet, ist die Finsternis, denn in der Dunkelheit kann es kein Licht geben, und der Schatten kann nicht überleben.",
  "Manche sagen, die Finsternis sei eine fette, träge, unbewegliche Macht. Eine Macht, die bleibt, wo sie hingehört, und nicht nach anderen greift, solange sie niemand stört. Alles, worum die Finsternis bittet, ist in Ruhe gelassen zu werden und alles für sich zu beanspruchen, was verlassen oder für immer in einer Kiste verschlossen ist. Was die Finsternis am meisten fürchtet, ist, entdeckt zu werden.",
  "Manche sagen, die Nacht sei eine strenge, stolze Macht. Eine Macht, die vor uns da war und bleiben wird, wenn nichts anderes mehr ist. Alles, was die Nacht will, ist die Welt zu beherrschen, dass alle Geschöpfe sie als die dunkle Herrin fürchten, die sie ist, und sie nicht mehr Zuflucht unter den Strahlen des Tages suchen muss. Doch was die Nacht am meisten fürchtet, sind die Sterne. Die geschworenen Feinde, die sie wie einen obszönen Umhang aus Licht trägt, die von der Dämmerung bis zum Morgen leuchten und den Geschöpfen darunter Hoffnung bringen. Das behaupten manche. Wer weiß, ob es stimmt."]}
]},

{id: "stress", t: "Schwerer Stress", p: 256, b: [
 "Wie du weißt, stellen die 12 Kästchen deiner Stressleiste deine körperliche und seelische Verfassung dar. Sie können sich oft füllen und leeren, manchmal mehrmals pro Sitzung. Doch wenn Körper und Geist wiederholter Belastung oder ernster Anstrengung ausgesetzt sind, ist Stress nicht so leicht abzuschütteln. Schwerer Stress ist eine besondere Art von Stress, die dir wirklich in den Knochen sitzt und sich nicht mit einer Nacht Schlaf entfernen lässt.",
 "Erleidest du Schweren Stress, musst du eine entsprechende Zahl Stresskästchen einkreisen, von links beginnend. Sind sie noch leer, werden die wegen Schweren Stresses eingekreisten Kästchen auch gleich ausgefüllt. Erleidest du zum Beispiel 2 Schweren Stress, musst du ihn auf deinem Bogen entsprechend markieren. Nach dem Erleiden Schweren Stresses lassen sich die eingekreisten Kästchen nicht wie üblich leeren. Außerdem wirst du bei jeder Menge Schwerem Stress Müde und kannst diesen Zustand nicht entfernen, egal was du tust, bis du auch den Schweren Stress entfernst.",
 {t: "h", x: "Schweren Stress erleiden"},
 "Du kannst auf 3 Arten Schweren Stress erleiden:",
 {t: "ul", x: [
  "**Nonstop:** Reist du Tag und Nacht ohne Rast, erleidest du 2 Schweren Stress. Das beschleunigt deine Reise, ist aber äußerst riskant. *„Im ersten Licht der Dämmerung erblickt ihr die vertraute Gestalt von Roadsend. Ein müdes Lächeln dehnt euer Gesicht, doch eure schmerzenden Füße erinnern euch daran, dass auch sie Ruhe brauchen. Ihr erleidet 2 Schweren Stress.“*",
  "**Entbehrung:** Bleibst du länger als einen Tag ohne ausreichend Nahrung oder Unterschlupf oder extremem Wetter ausgesetzt, erleidest du 1 Schweren Stress. *„Ihr wälzt euch unter einem trockenen Blatt, doch der Regen fällt weiter und spritzt überall hin. Diese Nacht wird lang und kalt. Ihr erleidet 1 Schweren Stress.“*",
  "**Kolossale Schläge:** Die meisten Colossi und Gegner mit dem Merkmal Verheerend können Schweren Stress verursachen. *„Die Krallen der Eule verfehlen euch um Haaresbreite, doch ihre schlagenden Flügel schleudern euch quer über die Lichtung und gegen einen Baum. Euer Rücken knackt, und ihr erleidet 1 Schweren Stress.“*"]},
 {t: "box", h: "Versagen und Schwerer Stress", b: ["Als Erzähler kannst du Charakteren auch wegen eines besonders katastrophalen Versagens Schweren Stress zuteilen. Versucht jemand zum Beispiel, einen Baum zu erklimmen, und scheitert, oder kann er nicht aus den Tiefen des Fountain emporschwimmen, kannst du ihm dennoch einen mühsamen Erfolg gewähren und als Folge der Anstrengung Schweren Stress zuweisen.", "Als Spieler kannst du auch freiwillig Schweren Stress auf dich nehmen, um Hilfe für eine besonders schwierige Aufgabe zu erhalten. Zum Beispiel, wenn du die ganze Nacht Wache hältst oder ohne Rücksicht auf deine Sicherheit auf einen Colossus zurennst. Der Erzähler entscheidet frei, ob er deinen Vorschlag annimmt."]},
 {t: "h", x: "Völlig erschöpft"},
 "Sammelst du 8 Schweren Stress und kreist das Entscheidende Kästchen deines Stresses ein, bist du völlig, total erschöpft. Zuerst erleidest du einen passenden Zustand, den der Erzähler nach den Umständen bestimmt. Meist ist das Krank oder Verletzt oder einer der Jahreszeit-Zustände. Bist du völlig erschöpft, tragen dich deine Beine kaum noch, jeder deiner Würfe ist ein automatisches Scheitern, und du kannst kaum noch sprechen. Bist du unterwegs, ist deine einzige Überlebenschance, dass dich jemand in den Sattel hebt oder wie ein Gepäckstück quer über den Rücken eines Reittiers lädt. Erleidest du aus seltenem und extremem Grund noch mehr Schweren Stress und kreist sogar das zwölfte Stresskästchen ein, trittst du ab und erleidest wahrscheinlich ein bitteres Schicksal.",
 {t: "h", x: "Schweren Stress heilen"},
 "Schwerer Stress lässt sich nicht wie normaler Stress behandeln und verschwindet nicht auf magische Weise nach einer Nacht Schlaf, nicht einmal bei einem Augenblick der Ruhe. Du kannst Schweren Stress nur entfernen, indem du ein Hospital oder eine andere sichere Herberge aufsuchst, wo du die nötige medizinische Versorgung erhältst. Nach 2 Tagen Pflege und völliger Ruhe kannst du 2 Kästchen Schweren Stress entfernen. Nach einer Woche kannst du deinen Schweren Stress vollständig löschen.",
 {t: "box", h: "Reittiere und Stress", b: ["Reittiere und Tiergefährten von Tierführern erleiden keinen Schweren Stress wie Littlings, was aber nicht heißt, dass sie gegen Erschöpfung immun sind. Ein Reittier oder Tiergefährte kann Tag und Nacht reisen oder ohne Nahrung bleiben, höchstens 4 Tage, bei einem Littling oder einer anderen bedeutenden Last auf dem Rücken nur 2. Danach sind auch sie völlig erschöpft und brauchen 3 volle Tage Ruhe."]}
]},

{id: "jahreszeiten", t: "Jahreszeiten", p: 258, b: [
 "Die Littlings des Outhold leben im Einklang mit den Jahreszeiten und zollen ihnen großen Respekt. Wie könnte es anders sein, wo Frühling, Sommer, Herbst und Winter Jahr für Jahr kommen und ihre Naturgewalt bei jedem Besuch und Abschied den Garten völlig verändert?",
 "Im Frühling ist das Outhold von bunten Blumen bedeckt, die Fülle an Pollen und Blütenblättern versprechen, mit zuckerreichen Früchten und Samen, aber auch überrannt von Bienenschwärmen und Wespenwolken, die Nektar trinken wollen. Im Sommer wird der Garten sonnig und heiß, und ein erfrischender Schattenfleck ist das Kostbarste. Im Herbst schütteln die Bäume ihre Blätter ab, und die faulsten Tiere beginnen ihr jährliches Festmahl vor dem langen und lang ersehnten Winterschlaf. Fällt schließlich der Winter, ist alles von einer eisigen weißen Schicht bedeckt, der große Fountain wird zum glitzernden Eisspiegel, und selbst das Last Ship steht still, im Eis erstarrt.",
 "Auf den kommenden Seiten sehen wir gemeinsam, wie sich der Garten durch die Jahreszeiten verändert. Zu jeder Jahreszeit findest du eine typische Form extremen Wetters und sogar 6 saisonale Wegkreuzungen zum Erkunden.",
 {t: "h", x: "Extremes Wetter"},
 "Das House hat ein großes Roof und vier feste Wände, die es schützen, der Garten aber ist jeder Art extremen Wetters ausgesetzt, wie Schnee und starkem Wind. Jeder Jahreszeit ist ein typisches extremes Wetterphänomen zugeordnet: Schnee im Winter, Wind im Frühling, Regen im Herbst und Schwüle im Sommer.",
 "Zu Beginn jedes Reisetags würfelt der Erzähler mit einem sechsseitigen Zahlenwürfel. Bei einer 1 bricht extremes Wetter über die Gruppe herein und erschwert die Reise noch mehr. Gab es nach 3 Reisetagen noch kein extremes Wetter, tritt es ab dem vierten Tag bei einer 1 oder 2 auf. Gab es nach 6 Reisetagen noch keines, tritt es ab dem siebten Tag auch bei einer 3 auf. Auch abseits der Straße kann der Erzähler extremes Wetter einsetzen, um eine Spielsitzung zu beleben oder denkwürdiger zu machen.",
 {t: "h", x: "Jahreszeit-Zustände"},
 "Hier siehst du die vier saisonalen Zustände. Jeder ist typisch für eine bestimmte Jahreszeit, kann dich aber das ganze Jahr über ereilen.",
 B("Gefroren", ["-1 auf alle Würfe im Bereich Krieg. Solange du Gefroren bist, kannst du keine Kreuz-Asse ausgeben, und erleidest du den Zustand Gefroren erneut, erleidest du stattdessen 2 Schweren Stress.", "Du kannst Gefroren werden, wenn du zu lange Frost oder Schnee ausgesetzt bist oder eine lange Winternacht ohne passenden Unterschlupf im Freien schlafen musst. Außerdem gibt es Bestien, die ein spezielles Gift absondern, das Littlings selbst im Hochsommer einfrieren kann.", "Du entfernst den Zustand mit einer warmen Mahlzeit und einer ganzen Nacht geschützt vor Kälte und Wetter. Alternativ entfernt ihn das Wayfarer-Manöver Heilmittel automatisch.", "*„Als ihr aus dem gefrorenen See auftaucht, merkt ihr erleichtert, dass ihr den Eichhörnchen entkommen seid. Einen Moment später klappern eure Zähne, und ihr zittert wie Espenlaub, während eure Kleidung gefriert. Ihr seid Gefroren.“*"]),
 B("Schniefend", ["-1 auf alle Würfe im Bereich Gesellschaft. Solange du Schniefend bist, kannst du keine Herz-Asse ausgeben.", "Du kannst Schniefend werden, wenn du zu lange starkem Wind ausgesetzt bist, von einem Staubsturm erfasst wirst oder von Kopf bis Fuß mit Pollen oder reizenden Pilzsporen bedeckt bist.", "Du entfernst den Zustand automatisch nach zwei Tagen. Alternativ entfernt ihn das Wayfarer-Manöver Heilmittel automatisch.", "*„Während der Wind in euren Ohren pfeift, merkt ihr, dass das Atmen durch die Nase immer schwerer wird und eure Augen vor Tränen anschwellen. Plötzlich erschüttert euch ein mächtiger Nieser, der winzige Meter weit hallt. Ratten! Ihr seid Schniefend!“*"]),
 B("Verschwitzt", ["-1 auf alle Würfe im Bereich Wissenschaft. Solange du Verschwitzt bist, kannst du keine Karo-Asse ausgeben, und trägst du Rüstung oder elegante oder pompöse Kleidung, erleidest du zusätzlich -1 auf alle Würfe.", "Du kannst Verschwitzt werden, wenn du zu lange in direkter Sonne oder extremer Hitze bleibst oder mehr als einen Tag ohne etwas zu trinken auskommen musst. Auch bei langer Schwüle oder zu langem Tragen zu warmer, schwerer Kleidung riskierst du, Verschwitzt zu werden.", "Du entfernst den Zustand, indem du einen Tag und eine Nacht an einem kühlen Ort ruhst und viel Wasser trinkst oder ein erfrischendes Bad in einem Teich nimmst. Alternativ entfernt ihn das Wayfarer-Manöver Heilmittel automatisch.", "*„Ihr geht immer langsamer und versucht, eure Augen vor der Helligkeit des Tages zu schützen und schaut zur Sonne auf, in der Hoffnung, sie möge bald untergehen. Doch das tut sie nie. Als ihr eure Feldflasche öffnet, merkt ihr, dass sie noch trockener ist als eure Kehle oder die Erde um euch. Ihr fühlt euch Verschwitzt.“*"]),
 B("Durchnässt", ["-1 auf alle Würfe im Bereich Straße. Senke deine Stufe Anstand um eins. Solange du Durchnässt bist, kannst du keine Pik-Asse ausgeben.", "Du kannst Durchnässt werden, wenn du mit Kleidung ins Wasser tauchst, im Regen reist oder von einer Welle überspült wirst. Manche kolossalen Bestien können dich sogar mit ihrem ekligen Sabber durchnässen.", "Du entfernst den Zustand, indem du die Kleidung wechselst und dich trocken rubbelst. Alternativ entfernst du ihn nach ein paar Stunden in der Sonne. Außerdem entfernt ihn das Wayfarer-Manöver Heilmittel automatisch.", "*„Als ihr einen großen Grashalm beiseiteschiebt, um alle durchzulassen, fällt ein riesiger Regentropfen direkt auf euren Kopf. Ihr nehmt euren triefenden Hut ab und wischt euch übers Gesicht. Es führt kein Weg daran vorbei: Ihr seid völlig Durchnässt.“*"])
]},

{id: "winter", t: "Winter", p: 260, b: [
 bild("s260-261-viii-winter-ganz", "voll"),
 "Der Winter ist die Jahreszeit des Frosts, der Stille und des langen Wartens. Drei Monate mit kurzen Tagen, von den ersten Schneefällen im Dezember bis zum Februar. Im Winter ist der Garten von einer Schicht weißen Schnees bedeckt, die alles verbirgt, die Landschaftsmerkmale verwischt und jede Reise äußerst gefährlich macht.",
 {t: "q", x: "Der Winter ist nur grausam zu den Törichten und Schlechtausgerüsteten.", wer: "Tavish „Tav“ McTavish"},
 "Wenn die ersten langen Schneefälle einsetzen, werden die Eingänge der Citadel einer nach dem anderen versiegelt, beginnend mit den entlegensten, und nur drei oder vier bleiben unter der wachsamen Aufsicht vertrauenswürdiger Gnomes offen. Wenige kommen in den kalten Monaten in die Citadel oder heraus. Nur Littlings mit sehr gutem Grund wagen es, alle anderen bleiben lieber warm in den gemütlichen Erdtunneln. Vor Ende Dezember wird der Fountain zum gefrorenen Spiegel, und Littlings besuchen ihn manchmal, um einen kalten, aber schönen Tag beim Schlittschuhlaufen zu verbringen. In dieser Jahreszeit ist der Frogstone-Thron leer, denn König Frog Jack zieht sich zu einem langen Winterschlaf in die Tiefen von Aquamarine zurück, bevor die erste Schneeflocke fällt. Doch der berühmte Frosch ist nicht die einzige Bestie des Outhold, die jeden Winter lange schläft oder in ähnlich träger Verfassung verharrt, und diese Geschöpfe können unglaublich gewalttätig sein, wenn man sie stört.",
 "Nach dem langen Herbst haben die meisten Bäume der Woodlands ihre Blätter verloren und sind dunkle Gewirre, die den Underwood nicht vor extremem Wetter schützen. Berge über Berge von Schnee türmen sich um das House, mehr als je ein Littling schaufeln könnte. Auf der Westseite ist das Green End gar nicht grün, aber der einzige echte Durchgang zum Backyard. Frondale ist dagegen so verschlossen, dass kaum ein Weg durch das Eis zu finden ist. Und das Roof, schon bei besten Bedingungen schwer erreichbar, wird zu einer einzigen schneebedeckten Eisfläche, so schwer zu überqueren, dass selbst die guten Littlings des Aviport die Luken dichtmachen müssen. Im Backyard halten die hohen Rushes den Schnee besser fern, sodass die Bürger des Shogunate die härteste Jahreszeit relativ sicher überstehen, sofern sie genug Vorräte für die kalten Monate angelegt haben.",
 {t: "h", x: "Winterregeln"},
 "Das typische extreme Wetter des Winters ist Schnee, der Erzähler kann aber auch Wind oder Regen einstreuen. Der typische Jahreszeit-Zustand ist Gefroren. Im Winter ist der ganze Garten von dicker Eis- und Schneedecke bedeckt, und die Sonne geht immer früher unter. Daher dauern alle Reisen doppelt so viele Reisetage.",
 {t: "box", h: "Extremes Wetter: Schnee", b: ["Im Winter tanzen kleine Schneeflocken durch den grauen Himmel und legen sich sanft aufs Gras, bis eine feste weiße Decke den ganzen Garten überzieht. Fällt dieser leichte Schnee, schauen die Kinder aus den Fenstern und rennen zum Spielen hinaus, während die Erwachsenen zur Schaufel greifen und ihre Einfahrten räumen. Die wirklichen Probleme beginnen, wenn der Schnee schwer und heftig fällt, als Schneesturm auf die Häuser kracht, den Reisenden auf den Rücken prügelt und alles auf der Straße gefrieren lässt. Der Schnee ist das furchterregendste Wetterphänomen des Outhold. Kein vernünftiger Littling würde ihm trotzen, außer es geht um Leben und Tod oder er ist bei Beginn schon unterwegs.", "Bei Schnee erleidest du -2 auf alle Würfe in Anmut, Ermittlung, Athletik, Vorsicht und Schießen. Du kannst diesen Abzug auf -1 senken, wenn du passende Winterkleidung oder einen sehr warmen Umhang trägst. Bist du zu lange den Winterelementen ausgesetzt, riskierst du, vom Wetter Gefroren zu werden. Du vermeidest den Zustand nur mit einem Erfolg bei Stärke + Krieg mit Schwierigkeit Kritisch oder höher, je nach Ernst der Lage."]},
 {t: "box", h: "Eiskalte Nächte", b: ["Winternächte sind besonders kalt, und nach Sonnenuntergang reichen dicke Kleidung und Pelzumhänge nicht, um dich warm und behaglich zu halten. Beim Lagern im Winter musst du stets ein Feuer entfachen, sonst genießt du nicht die Vorteile eines Unterschlupfs. Die einzige Ausnahme: Du lagerst im Underground oder schläfst neben einem großen pelzigen Tier wie einer Maus oder einem Maulwurf."]},
 {t: "box", h: "Winter im House", b: ["Der Winterfrost streckt seine eisigen Finger auch ins House und erreicht fast jeden Raum, außer den Basement, wo die Hitze des Falschen Feuers die Wände das ganze Jahr wärmt. Im Vertrauen: Der Winter im House ist weit weniger grausam und gefährlich als der im Outhold, und wer anderes behauptet, meist Stadtvolk, hat nie einen Fuß nach draußen gesetzt. Rund um Faeriyev, am Westlichen Edge von Tuberdam und im Bereich des Yule Tree im Living Room stehen die Fenster einen Spalt offen und lassen Kälte, Schnee und Wind herein."]},
 {t: "h", x: "Winter-Wegkreuzungen"},
 "Hier folgen 6 Wegkreuzungen, die zu einer Winterreise passen. Der Erzähler kann frei eine aus der Liste wählen, zufällig würfeln oder eigene, neue Wegkreuzungen erfinden.",
 B("Schlafender Colossus", ["Ihr findet einen sicheren Durchgang durch eine Höhle, einen unterirdischen Tunnel, ein Gebüsch oder einen hohlen Stamm. Gerade als alles bestens aussieht, lässt euch ein unheimliches Geräusch zusammenzucken, und ihr merkt, dass ihr direkt in den Bau eines tief schlafenden kolossalen Geschöpfs geraten seid, vielleicht beim Winterschlaf.", "Geht ihr weiter, müsst ihr sehr vorsichtig sein, könnt eure Reise aber sicher vor extremem Wetter und anderen Fallstricken fortsetzen, es sei denn, ihr weckt den Colossus versehentlich. Alternativ kehrt ihr um und nehmt den langen Weg, wodurch die Reise einen Tag länger dauert."]),
 B("Medizinische Vorräte", ["Am Ende der Straße ragt ein seltsames Holzgebilde aus dem Schnee. Es ist ein kleiner, fast völlig vereister Karren voller Impfstoff-Fläschchen, Medizin und anderer medizinischer Vorräte. Ein zerknitterter Brief verrät, dass die Vorräte vor etwa einem Monat in eine nahe Stadt hätten gelangen sollen.", "Bringt ihr die Vorräte an ihr Ziel, müsst ihr einige Tage zur Reise addieren, werdet aber mit Essen, Unterkunft und der Dankbarkeit der Stadtbewohner belohnt. Plündert ihr den Karren und geht eurer Wege, bekommt ihr zwei Stresslinderungstränke, zwei Allheilmittel und zwei Frostschutzbalsame."]),
 B("Gefrorener See", ["Zwischen der schneebedeckten Vegetation liegt eine völlig gefrorene Pfütze. Ein magischer, sicherer Ort, an dem ihr „Schlittschuh“ laufen und euch an eine glücklichere Zeit erinnern könnt.", "Haltet ihr an, um als Gruppe Spaß zu haben, entfernt ihr 3 Stress und einen Zustand eurer Wahl aus Verängstigt, Beschämt oder Schuldig. Aber die Zeit vergeht wie im Flug, und am Ende addiert ihr einen Reisetag. Bleibt ihr nicht, erreicht ihr bald einen Aussichtspunkt mit Blick auf einen schönen Sonnenuntergang, wo ihr leicht Unterschlupf für die Nacht findet."]),
 B("Kiefernzapfen-Hütte", ["Nicht weit von der Straße seht ihr einen Haufen Kiefernzapfen, der sich auf den zweiten Blick als nettes Winterhäuschen erweist. In dem gemütlichen Zapfenhaus lebt eine anständige Barghest-Familie, einfache, gastfreundliche Leute, die euch ohne Zögern aufnehmen. Beim Abendessen erfahrt ihr, dass die Familie von Banditen geplagt wird, die ihre Mäuse stehlen wollen.", "Helft ihr und vertreibt die Banditen, erhaltet ihr ihre ewige Dankbarkeit, Essen und eine Rennmaus mit schneeweißem Fell. Alternativ kümmert ihr euch um eure Angelegenheiten und lasst Banditen und andere Fallstricke 2 Tage hinter euch."]),
 B("Zugeschneiter Pass", ["Vor euch öffnet sich eine lange, in frischen Schnee gegrabene Schlucht, flankiert links und rechts von zwei instabilen Schneewänden.", "Ihr könnt auf dem Schneekamm gehen, wo das Gelände fester ist. Dann seid ihr aber leicht zu sehen, und Bestien und Littlings können eure Bewegungen leicht verfolgen. Zudem bietet der höchste Teil des Passes keinen Schutz vor dem Wetter. Geht ihr stattdessen am Grund der Schneeschlucht weiter, müsst ihr darauf achten, absolut keinen Lärm zu machen und nie eine Feuerwaffe abzufeuern. Ein falscher Schritt könnte eine Lawine auslösen."]),
 B("Feind in Gefahr", ["Ihr stolpert über einen alten Feind oder einen Littling einer Fraktion, der mindestens einer von euch feindlich gesinnt ist. Der Feind ist schwer verwundet und könnte noch vor Tagesende sterben, würde aber lieber sterben, als Hilfe von euch anzunehmen.", "Helft ihr ihm, bremst der Feind euer Tempo, weil er kaum gehen kann und nicht aufhört zu grummeln. Nach zwei Tagen unterwegs bringt ihr ihn zu seinen Freunden zurück und findet vielleicht sogar Gemeinsamkeiten. Ignoriert ihr ihn, stoßt ihr am nächsten Tag auf eine Gruppe, die verzweifelt nach ihm sucht. Sie geben euch die Schuld am Tod ihres Freundes, und ihr riskiert, gefangen und wegen Verrats vor Gericht gestellt zu werden."])
]},

{id: "fruehling", t: "Frühling", p: 264, b: [
 bild("s265-viii-spring", 240),
 "Der Frühling ist die Jahreszeit der Blumen, des Lebens und der Liebe. Er beginnt am 1. März, wenn der Schnee schmilzt und Gras und Blätter freigibt, und endet nach dem Mai, wenn die Hitze überwältigend wird. Wenn du das Outhold nur einmal im Leben besuchen willst, tu es im Frühling, denn dann sind die Temperaturen mild und der Himmel klar und blau. Gleichzeitig explodiert die Landschaft in Rot, Gelb, Blau, Violett und tausend Farben, als hätte jede Blume im Garten verabredet, gleichzeitig zu blühen, um das Ende des Winters zu feiern.",
 "Werden die Tunnel der Citadel einer nach dem anderen geöffnet, füllen sich die Barrens mit Reisenden und Händlern. Im Fountain öffnen duftende Seerosen und andere schwimmende Blumen ihre Blüten auf der Wasseroberfläche, wo Littlings sie als zarte Wasserfahrzeuge nach Frogstone nutzen können. Die Woodlands bekommen wieder ein undurchdringliches Blätterdach, dicht genug, den Underwood vor Regen zu schützen und die Abende der Littlings in Twigbridge mit sanftem Rascheln zu verzaubern. Im Mai feiern die Littlings dieser Region das uralte Beltane, ein feierliches Fest, das an den Fall des Dèndronaos-Baums erinnert und seine Wiedergeburt begrüßt.",
 "Die Luft bei den Brambles beginnt von hungrigen Bienen und Wespen zu wimmeln, was das Erklimmen des Efeus zum Roof noch gefährlicher macht. Frondale wird dagegen wieder zur besten Route für Littlings Richtung Backyard. Auf der anderen Seite des House wird das Green End zu einem Sumpfland mit stehenden Tümpeln und reißenden Flüssen, Folge der Schneeschmelze. Die hohen Rosen von Mirkbush blühen nur im Frühling, und ihre unerreichbaren Dornen dienen zur Herstellung der seltenen Scimithorns, die romantische und schurkische Duellanten so gern führen. Man kann angesichts der Poesie der Natur nicht gleichgültig bleiben, die die seltenste und kostbarste Blume schuf und sie zwischen den dunkelsten Stacheln des düstersten Waldes im ganzen Garten erblühen ließ.",
 "Das Spiegelbild dieses Frühlingsparadoxons ist die schöne Präfektur Hanado im Norden der Rushes, die sich jeden Frühling in eine herrliche Wiese verwandelt, Scharen von Besuchern anzieht und alle vor Ehrfurcht erschüttert. Doch die bunten Knospen von Hanado verbergen eine teuflische, gefräßige Kreatur. Eine große Gottesanbeterin in allen Farben des Regenbogens, den einheimischen Shinigami als Gespenst der Blühenden Wiese bekannt.",
 {t: "h", x: "Frühlingsregeln"},
 "Im Frühling blühen die Blumen, und die Tiere des Gartens verfallen der Euphorie der Jahreszeit. Das typische extreme Wetter des Frühlings ist Wind, der Erzähler kann aber auch Regen einstreuen. Der typische Jahreszeit-Zustand ist Schniefend. Bist du zu lange direkt dem Wind ausgesetzt, kann der Erzähler einen Wurf auf Stärke + Straße verlangen. Scheiterst du, beginnst du zu niesen und wirst Schniefend. Auch die Windböen wirbeln große Staub- und Pollenwolken auf, die Augen und Nase reizen und dich ebenfalls Schniefend machen können. Bei starkem Wind können Faeries und Fae nicht fliegen, und wer es versucht, wird von den Strömungen zu Boden geschleudert.",
 {t: "box", h: "Extremes Wetter: Wind", b: ["Der Garten wird von der freundlichen wilden Luft gestreichelt, die durch die Äste fährt, die Tage erfrischt und den Grasteppich des Rasens klärt. Doch hin und wieder wird die Luft unruhig und beginnt sich zu winden, zu schreien, zu schnaufen und so heftig zu toben, dass selbst die Fenster des House klappern. Im Frühling ist Wind das häufigste extreme Wetterphänomen. Er kämmt Blätter und Gras und wirft Littlings mit unaufhaltsamer Kraft um.", "Bist du dem Wind ausgesetzt, erleidest du eine Behinderung auf alle Würfe zum Klettern oder zum Schießen auf mehr als Kurze Distanz, und du musst äußerst vorsichtig vorgehen, um nicht herumgeschleudert zu werden. Außerdem können bei starkem Wind alle Bestien des Gartens deine Witterung leicht aufnehmen und dich finden, egal wie gut du versteckt bist. Das Reisen unter diesen Bedingungen setzt dich stets Gefahr aus."]},
 {t: "box", h: "Paarungszeit", b: ["Im Frühling beginnt bei den Säugetieren des Outhold die Paarungszeit, und sie werden von Euphorie erfasst. Mäuse, Maulwürfe, Eichhörnchen und alle anderen pelzigen Geschöpfe des Gartens werden besonders unternehmungslustig und nähern sich viel öfter Littling-Siedlungen, wobei sie manchmal ohne ersichtlichen Grund lästig oder sogar bedrohlich werden."]},
 {t: "box", h: "Frühling im House", b: ["Der Frühling im House ist ein Anblick: Die Räume und Flure sind kühl, aber nicht kalt, und Essen und sauberes Wasser findet man praktisch überall. Vielleicht sind pelzige Tierchen wie die Mäuse und großen Ratten der Inbetweens euphorischer oder aggressiver als sonst, aber nichts, womit Tierführer und Jäger nicht fertig würden. Zumindest bis die Dinge außer Kontrolle geraten. Auch im House wehen die Frühlingswinde stark und mächtig und können erstaunlich lästig werden, besonders im Long Hallway und auf den Great Stairs."]},
 {t: "h", x: "Frühlings-Wegkreuzungen"},
 "Hier folgen 6 Wegkreuzungen, die zu einer Frühlingsreise passen. Der Erzähler kann frei eine aus der Liste wählen, zufällig würfeln oder eigene, neue erfinden.",
 B("Süßer Kampf", ["Lautes Bienensummen erfüllt die Luft. Eine Gruppe zwielichtiger Jäger kämpft gegen einen Schwarm wütender Bienen und versucht, einen Stock voll kostbarem Honig zu erobern.", "Helft ihr den Jägern, belohnen sie euch mit Honig im Wert von 15 Münzen und zeigen euch einen klaren, wettergeschützten Weg. Stellt ihr euch dagegen auf die Seite der Bienen, bedankt sich eine von ihnen, indem sie Pollen auf euren Kopf entlädt. Das nächste Mal, wenn ihr in Gefahr seid, eilen euch die Bienen zu Hilfe und tun ihr Bestes, den Gefallen zu erwidern."]),
 B("Kleine Mäuse", ["Nicht weit entfernt seht ihr ein Städtchen oder ein freundliches Lager, wo ihr endlich ruhen könnt. Ihr müsst nur ein wenig das Tempo anziehen, und ihr seid zum Abendessen dort. Doch kurz vor Sonnenuntergang hört ihr das jammernde Fiepen einer Mäusemutter, die unter einem Pilz am Boden liegt und gleich gebären wird.", "Geht ihr weiter, erreicht ihr die Stadt vor Einbruch der Nacht, mit gutem Essen und sicherem, wettergeschütztem Schlafplatz. Wollt ihr der Maus helfen, müsst ihr die Nacht hier verbringen, der Geburt beistehen und andere Tiere fernhalten, ohne schlafen oder lagern zu können. Bei Morgengrauen aber wählt eines der neugeborenen Mäuse einen der Littlings als Mutter und folgt ihm 2 ganze Jahreszeiten und hilft ihm, als hätte er das Merkmal Kleiner Freund. Ab der dritten Jahreszeit ist die Maus groß genug, um als Reittier zu dienen."]),
 B("Gefallenes Ei", ["Einige neugierige Tiere haben sich um etwas versammelt, das wie ein runder Kiesel aussieht, aber ein aus dem Nest gefallenes Ei ist.", "Findet ihr einen Weg, das Ei zu seiner Mutter zurückzubringen, die wahrscheinlich hoch in den Zweigen eines Baums sitzt, könntet ihr mit dem Skyrider-Vertrag belohnt werden. Dafür müsst ihr aber mit einer hungrigen Schlange um das Ei kämpfen. Alternativ versucht ihr, selbst auf dem Ei zu sitzen, oder verkauft es für bis zu 9 Münzen. Ignoriert ihr das Ei, kreisen seine Eltern bald in der Luft und suchen es. Die nächsten 2 Tage begegnet ihr keiner anderen Bestie, müsst aber auf Vogelangriffe achten."]),
 B("Blumenwiese", ["Vor euch liegt ein schönes Feld hoher bunter Blumen.", "Geht ihr durch die Wiese, seid ihr mehrere Tage vor dem Wind sicher und findet reichlich Essen, wann immer ihr lagern wollt, landet aber im Jagdgebiet einer Gottesanbeterin, einer Schlange oder vielleicht sogar einer Teufelsblumen-Gottesanbeterin. Meidet ihr die Wiese, führt euch die Straße zu einem steilen Loch im Boden. Beim steilen Aufstieg müsst ihr sehr darauf achten, wohin ihr den Fuß setzt, und findet mehrere Eingänge, die direkt in den Underground führen."]),
 B("Frühlingsschauer", ["Ein unerwarteter, aber warmer Regenschauer hat einen echten Fluss entstehen lassen, der sich durch den Garten schlängelt und direkt zu eurem Ziel fließt.", "Findet ihr einen Weg, ein Boot zu bauen, etwa aus einem Pilzhut oder einem festen Blatt, könnt ihr die Strömung nutzen und 2 Reisetage sparen. Kurz vor dem Ziel begegnen euch aber furchterregende Stromschnellen, die die Reise erschweren. Alternativ geht ihr am Fluss entlang. Dann habt ihr reichlich Wasser und eine einfache Möglichkeit, eure Spuren zu verwischen."]),
 B("Samurai in Not", ["Ihr merkt, dass ihr von Spuren eines kürzlichen Handgemenges umgeben seid. Die Fußabdrücke führen vom Weg weg zu einem gefährlichen Ort in der Höhe. Dort liegt ein Shinigami-Samurai an der Schwelle des Todes oder vielleicht sogar der Totheit verfallen, der eure Hilfe braucht. Aber von hier spürt ihr, dass der Wind an Fahrt gewinnt.", "Bleibt ihr, um dem Samurai zu helfen, steht er in eurer Lebensschuld und folgt euch als persönlicher Leibwächter, bis er den Gefallen erwidert hat. Leider müsst ihr für die verlorene Zeit zahlen und seid die nächsten 5 Tage einem endlosen Wind ausgeliefert. Überlasst ihr den Shinigami seinem Schicksal, bleibt ihr dem Wind voraus, vermeidet extreme Wetterphänomene für 5 Tage und meidet sogar wilde Bestien, die eure Witterung aufnehmen könnten."])
]},

{id: "sommer", t: "Sommer", p: 268, b: [
 bild("s269-viii-summer", 240),
 "Der Sommer ist die Jahreszeit der Sonne, des Lichts und endloser Abendfeste. Er schleicht auf Zehenspitzen mit dem Beginn des Juni herein, und ehe man sich versieht, hat die Hitze alles übernommen und weigert sich bis Ende August zu gehen, manchmal noch länger. Im Sommer reisen wohlhabende oder unternehmungslustige Littlings für ein paar Wochen oder Monate an den Edge des Fountain, wo sie leicht ein erfrischendes Bad nehmen können. Noch Glücklichere können sich sogar eine Luxusvilla in Frogstone leisten, das in den heißen Monaten das beliebteste Ziel ist.",
 "Sobald man sich vom Fountain entfernt, ändert sich die Lage drastisch, denn die gesamten Grasslands und Barrens werden zu einer trockenen, erstickenden Weite unter der sengenden Sonne. Hier müssen Littlings mit einer Dürre rechnen, die so schlimm ist, dass die Citadel manchmal das Wasser rationieren muss, das sie im Frühling geduldig gehortet hat. Besser ist es im Underwood, wo die hohen Äste die Sonne abhalten. Doch auch die Woodlands sind gegen Schwüle und Dürre nicht immun, und die Einheimischen graben rasch sehr tiefe Brunnen, jedes Jahr tiefer, in dem verzweifelten Versuch, Regenwasserreserven zu finden.",
 "Werden die Tage glühender und schweißtriefender, füllen sich die endlosen Sonnenuntergänge und noch warmen Abende mit fröhlichem Jubel, wenn Littlings jung und alt zum Trinken, Feiern und Tanzen bis spät in die Nacht zusammenkommen. Denn der Sommer ist voller Tausender Feste, Partys und kleiner Feiern, und jeder Anlass ist recht, fröhlich zu sein. Das wichtigste Fest von allen, draußen wie drinnen, ist Litha, die Feier zum Beginn der schönen Jahreszeit.",
 "Im Backyard ist es nicht viel anders. In der Präfektur Mizuken verdunsten die vielen Teiche und Wasserwege langsam und trocknen aus, bis nur die großen übrig sind, zusammengedrängt in einem schattigen Gebiet an der Seite des House. Die Präfektur Hanado verliert dagegen die meisten Blumen und wird zu einem Streifen gelben Grases, und alle Touristen und Gelegenheitsreisenden, die im Frühling kamen, verschwinden. In Fukami entzündet die erstickende Sommerhitze oft kleine Waldbrände, die die örtliche Papierindustrie und die Arbeit der Origami-Meister bedrohen. Dagegen hat der sogenannte Fremde Daimyo, Theodore Knox, viele Blätterlagerhäuser gebaut, die unabhängig von den Wetterbedingungen volle Produktivität sichern.",
 bild("s270-viii-summer", 260),
 {t: "h", x: "Sommerregeln"},
 "Im Sommer wird das Gras trocken, und der Garten ist von intensivem Licht und trockener, erstickender Hitze durchdrungen. Das typische extreme Wetter des Sommers ist Schwüle, der Erzähler kann aber auch Regen einstreuen. Der typische Jahreszeit-Zustand ist Verschwitzt.",
 {t: "box", h: "Extremes Wetter: Schwüle", b: ["Die Sommertage werden lang, während die Sonne immer höher steigt und um ihren Platz am Himmel kämpft. Das Leuchten des Tagesgestirns wird von allen geschätzt, denn Jung und Alt können endlich ihre Knochen wärmen und die Wangen rösten. Doch lässt sich die Sonne mitreißen, beginnt sie zu brennen, und die Luft im Garten wird still und trocken und zieht sich zusammen, als suche sie Schutz im Schatten des Underground. Das furchterregende extreme Wetter des Sommers ist die Schwüle. Eine Welle glühender, erstickender Hitze, die die Sinne vernebelt und die Kehle austrocknet.", "Bei Schwüle erleidest du -1 auf alle Würfe in den Bereichen Gesellschaft und Wissenschaft und musst hydriert bleiben, sonst bekommst du einen Sonnenstich. Während einer Schwüle erträgst du keine Winterkleidung oder irgendeine Rüstung. Wer die Hitze ignoriert und zu viel trägt, erleidet 1 Stress und wird Verschwitzt, bis er sich abkühlen kann. Bei Schwüle in der Sonne zu reisen ist eine unbedachte Idee. Wer den Elementen trotzt, senkt seine Stufe Anstand um eins und muss eine ganze Feldflasche trinken, um nicht Verschwitzt zu werden."]},
 {t: "box", h: "Nachts reisen, tagsüber schlafen", b: ["Im Sommer wird das Wetter so heiß, dass manche Littlings lieber nach Sonnenuntergang reisen und bei Tagesanbruch schlafen gehen. So lassen sich die Nachteile der Schwüle leicht vermeiden, doch man ist auch größeren Risiken und mehr wilden Bestien ausgesetzt. Jedem das Seine."]},
 {t: "box", h: "Sommer im House", b: ["Stadtvolk sagt, das House bleibe im Winter warm und im Sommer kühl, doch das hat mir auch die liebe alte Dame erzählt, die mir das Haus in Bookshire verkaufte, von dem ich schreibe. Die Wahrheit ist, dass die Hitze in den Sommermonaten das House überfällt, immer weniger erstickend wird, je weiter man zum Long Hallway reist, und dann unten im Basement noch glühender. Und die Schwüle reicht wirklich überall hin. Nicht einmal mein Arbeitszimmer verschont sie, sodass ich nun buchstäblich Schweiß auf mein Lebenswerk tropfe."]},
 {t: "h", x: "Sommer-Wegkreuzungen"},
 "Hier folgen 6 Wegkreuzungen, die zu einer Sommerreise passen. Der Erzähler kann frei eine aus der Liste wählen, zufällig würfeln oder eigene erfinden.",
 B("Brillante Erfindung", ["Ein seltsamer Littling hat eine Maschine erfunden, die in der Luft oder über dem Wasser mit voller Geschwindigkeit fliegen kann. Er hat sie aber nie getestet. Stimmt ihr zu, das Fahrzeug zu testen, läuft zunächst alles bestens, und ihr spart sogar 2 Reisetage. Dann erwischt euch das extreme Wetter, das Fahrzeug versagt, und ihr riskiert, euer Leben und alle Vorräte zu verlieren.", "Lehnt ihr das Angebot ab, stoßt ihr 2 Tage später auf das zerstörte Fahrzeug und findet den Erfinder, der verzweifelt seine Vorräte vor einem Grillenrudel zu schützen versucht."]),
 B("Duell bei Sonnenuntergang", ["In einem winzigen Dorf steht ein Pistolen- oder Schwertduell bevor. Bei Sonnenuntergang kommt ein arroganter Soldat oder Bandit her, um einen von den Dorfbewohnern gewählten Champion herauszufordern, um einen langen Streit beizulegen. Der Champion ist ein guter Littling, wenn auch etwas rau und knapp, doch er ist schwer verwundet und nicht in der Verfassung zu kämpfen.", "Nimmt einer von euch seinen Platz ein und gewinnt das Duell, erntet ihr den Respekt der Einheimischen, werdet aber zum Todfeind des Herausforderers. Stellt ihr euch auf die Seite des Herausforderers oder findet eine diplomatische Lösung, bietet er euch 2 Tage lang Geleit und sicheren Durchgang vor Fallstricken und extremem Wetter. Ignoriert ihr die Sache, verliert der Champion das Duell, und eure Straße wimmelt die nächsten 3 Tage von böswilligen Littlings, die auf euch losgehen."]),
 B("Liebenswerter Flüchtling", ["Ein hungriger, in Lumpen gekleideter Littling bittet euch um Hilfe, weil jemand ihn verfolgt. Auch wenn der Littling ungemein herzlich ist, merkt ihr bald, dass die Verfolger ihre Gründe haben, denn er schuldet ihnen 100 Münzen, die er beim Glücksspiel verloren hat.", "Übergebt ihr den Flüchtling, belohnen euch die Verfolger mit 10 Münzen sowie Wasser und Proviant für die Nacht. Helft ihr dem Flüchtling oder begleicht seine Schuld, bedankt er sich mit allen Höflichkeiten und geht seiner Wege. In der nächsten Jahreszeit trefft ihr ihn wieder, aufgemuntert und schick gekleidet, bereit, euch zu helfen."]),
 B("Sommerfest", ["Die ohrenbetäubende Musik und die bunten Lichter eines Jahrmarkts erregen eure Aufmerksamkeit. Offenbar feiert ein nahes Dorf fröhlich.", "Geht ihr weiter, verläuft der Abend friedlich ohne extremes Wetter, und beim Lagern merkt ihr, dass ihr einen Reisetag gespart habt. Nehmt ihr dagegen am Fest teil, genießt ihr einen Abend mit Essen, Tanz und Spielen. Am Ende seid ihr so entspannt, dass ihr die Zustände Verschwitzt, Beschämt, Verwirrt und Verängstigt entfernen könnt. Littlings ohne einen dieser Zustände können 1 Schweren Stress entfernen."]),
 B("Eidechsenführer", ["Ein alter, rustikaler Littling führt ein Dutzend junge, unruhige Eidechsen spazieren, als plötzlich eines der Tiere aus der Gruppe ausbricht und durch die Vegetation rennt. Der Alte verliert nicht die Fassung und sagt euch sogar, nicht einzugreifen, denn diese Eidechse sei schon dreimal ausgerissen und ein hoffnungsloser Fall.", "Folgt ihr dem Rat des Führers, könnt ihr 3 Tage mit ihm reisen und dank seiner Ortskenntnis extreme Wetterphänomene umgehen und jede Nacht Unterschlupf finden. Jagt ihr dagegen die Eidechse, macht euch das kleine Tier einen ganzen Tag verrückt und bringt euch in Teufels Küche, bevor es sich an euch bindet. Nach einer Jahreszeit ist die Eidechse groß genug als Reittier."]),
 B("Die letzte Quelle", ["Ein Glitzern in der Ferne verrät den Ort einer Pfütze oder kleinen Süßwasserquelle.", "Trinkt ihr dort, entfernt ihr den Zustand Verschwitzt und füllt alle Feldflaschen randvoll. Doch sobald ihr nachlässig werdet, greift euch eine durstige Ratte oder eine in der Vegetation versteckte Gottesanbeterin an. Ignoriert ihr die Quelle, um keine kostbare Zeit zu verlieren, findet ihr die nächsten 5 Tage keinen Tropfen Wasser, und mittendrin tappt ihr unwissentlich in die Falle eines überwucherten Ameisenlöwen. Besiegt ihr ihn und grabt durch seinen Sand, findet ihr die Reste eines Karrens mit einem vollen Wasserkrug, 2 Stresslinderungstränken, 2 Erfrischungstonika und ungewöhnlicher eleganter Kleidung."])
]},

{id: "herbst", t: "Herbst", p: 272, b: [
 bild("s273-viii-autumn", 240),
 "Der Herbst ist die Jahreszeit des fallenden Laubs, der Erinnerungen und der Reue. Er beginnt im September, wenn die leichten Regen die Hitze fortspülen, und dauert bis November oder weit in den Dezember, wenn der Schnee zu fallen beginnt. Im Herbst werden die Tage kürzer und kälter und mahnen die letzten Nachzügler, reichlich Vorräte für den Winter anzulegen, denn wenn der Schnee kommt, ist es zu spät. Wie die Littlings im ganzen Garten streifen auch die Bestien, besonders die vor dem Winterschlaf stehenden Colossi, überall auf der Suche nach Nahrung umher, um ihren Winterbau oder ihren Magen zu füllen. Deshalb muss man beim Reisen abseits der Stadt äußerst vorsichtig sein.",
 {t: "q", x: "Weise ist der Littling, der im Herbst alles beiseitelegt, denn er weiß, bald wird er nichts mehr haben. Weise ist der Littling, der im Herbst genießt, was er hat, denn er weiß, bald wird er nichts mehr haben.", wer: "Shappa"},
 "Wenn es regnet, was in dieser Jahreszeit nicht selten ist, wird der Fountain von riesigen Wellen gepeitscht, die manchmal zu regelrechten Tsunamis werden. Die Bäume der Woodlands verlieren immer mehr Blätter und können das Wasser kaum noch vom Durchdringen ihrer Äste abhalten. Der Underwood wird zu einem Teppich aus roten und gelben Blättern, die durch das Wetter feucht und matschig werden. Ein perfektes Versteck für Hunderte und Aberhunderte lästiger Insekten, Spinnen, Frösche und sogar Schlangen, die im schlammigen Feuchtland bestens zu Hause sind.",
 "Im Backyard wird der Herbst zutiefst verehrt, nicht nur weil die Shinigami Vorräte für die kälteren Monate sammeln, sondern auch weil jeder seinen Teil beitragen muss, um die Reserven des örtlichen Daimyo und der Shogun Yōkai Jorōgumo zu füllen. Außerdem feiert das Shogunate die gesamte erste Novemberwoche Samhain und erinnert an den Tag, an dem Sluagh und Shinigami im House ankamen. Zu diesem wichtigen Fest gedenken die Shinigami ihres wehmütigen Abschieds von Farbeyond und aller Littlings, die nie aus der Totheit erwachten. Dazu fertigen sie Hunderte Laternen aus durchscheinenden Blütenblättern, die sie anzünden und in den Nachthimmel steigen lassen.",
 {t: "h", x: "Herbstregeln"},
 "Im Herbst färben sich die Blätter gelb und rot und fallen im Underwood. Und da die Tage kürzer werden, dauert jede Reise 1 zusätzlichen Reisetag je 4. Das typische extreme Wetter des Herbstes ist Regen, der Erzähler kann aber auch Wind einstreuen. Der typische Jahreszeit-Zustand ist Durchnässt.",
 {t: "box", h: "Extremes Wetter: Regen", b: ["Wenn der Himmel dunkel wird wie die Decke des House und bedrohliche Wolken sich wie eine Phalanx der Great Imperial Army zusammenballen, laufen die Littlings im ganzen Garten in Deckung und verriegeln ihre Häuser, um dem Sturm zu entgehen. Das typische extreme Wetter des Herbstes ist der Regen, ein Wasserschwall, der Gras und Bäume prügelt und die Erde in Schlamm verwandelt.", "Regen ist eine Behinderung auf alle Würfe in den Bereichen Krieg und Straße. Kämpfst du gegen Littling-Gegner, sind auch sie vom Wetter behindert, sodass du diesen Abzug ignorieren kannst. Trifft dich ein Regentropfen direkt, ist es, als würde jemand ein großes Fass auf deinen Kopf entleeren. Scheiterst du bei einem Wurf zum Rennen oder Klettern im Regen, riskierst du stets Stress und den Zustand Durchnässt.", "Bei Regen ist Reisen im Freien fast unmöglich. Wer einen Reisetag unter dem prasselnden Regen wagt, wird unweigerlich Durchnässt und erleidet 1 Schweren Stress. Außerdem ist Regen extrem laut, übertönt alle anderen Geräusche, sodass Verständigung mit jemandem jenseits der Kurzen Distanz fast unmöglich ist. Schließlich können weder Faeries noch Fae bei Regen fliegen."]},
 {t: "box", h: "Blätterbündel", b: ["Wenn du ins Wasser tauchen willst und etwas Zeit hast, kannst du ein Blatt suchen und darin Kleidung und Waffen bündeln. So transportierst du deine Sachen, ohne sie nass zu machen und ohne den Zustand Durchnässt zu erleiden."]},
 {t: "box", h: "Herbst im House", b: ["Im Garten sind die Herbsttage kürzer als normal, im House ist es noch schlimmer, weil die wenigen offenen Fenster kaum Licht hereinlassen. Die einzigen Ausnahmen sind der Basement, wo das Licht des Falschen Feuers das ganze Jahr auf die verrostete Große Klinge scheint, und der Hearth dank der milderen Flamme des Kamins. Der Regen gelangt meist nicht ins House und kommt nur selten durch die Decke des Top Hallway. Der Herbstwind ist dagegen noch aggressiver als die Frühlingsluft und weht besonders hart durch den Schacht der Great Stairs."]},
 bild("s276-viii-autumn", 200),
 {t: "h", x: "Herbst-Wegkreuzungen"},
 "Hier folgen 6 Wegkreuzungen, die zu einer Herbstreise passen. Der Erzähler kann frei eine aus der Liste wählen, zufällig würfeln oder eigene erfinden.",
 B("Kriegskäfer", ["Ein Militär-Tierführer sucht einen Kriegskäfer, das mürrische Reittier eines hohen Beamten. Beim Umsehen erfahrt ihr, dass das stolze Tier gerade gegen eine große Einsiedlerspinne kämpft.", "Helft ihr dem Käfer und bringt ihn zum Lager des Führers zurück, belohnt man euch mit 5 Münzen und einem Rat, mit dem ihr extremes Wetter 3 Tage vermeiden könnt. Alternativ behaltet ihr den Käfer als Reittier. Das Tier ist eine ganze Jahreszeit extrem schlecht gelaunt, lernt dann aber, euch zu vertrauen."]),
 B("Überfluteter Tunnel", ["Ein Blitz zerreißt den Himmel und kündigt einen Sturm an. Gerade als ihr meint, dem Regen entgangen zu sein, merkt ihr, dass es in der Nähe einen Zugang zu einem unterirdischen Tunnel gibt. Der Eingang wurde vor langer Zeit zugenagelt, doch einmal geöffnet führt er direkt in ein Gewirr von Tunneln aus der Zeit des Household War.", "Steigt ihr in den Underground, läuft zunächst alles glatt, bis Wasser in den Tunnel zu fließen beginnt und eure Reise zu einer verzweifelten Flucht wird, während alles einstürzt. Nach diesem Rückschlag könnt ihr 2 Tage reisen, ohne extremem Wetter zu begegnen. Bleibt ihr im Freien, lässt der Regen 3 Tage und 3 Nächte nicht nach. Der einzige Trost: Bei diesem Wetter wagt sich auch kein Tier oder Insekt heraus, um euch zu belästigen."]),
 B("Hinauf oder hinunter", ["Der sintflutartige Regen der letzten Tage hat eine Pfütze so breit wie das Meer des Fountain geschaffen. Setzt ihr den Weg fort, müsst ihr ein Wasserfahrzeug finden oder mindestens 3 Tage schwimmen. Im Wasser seid ihr vor Bestien sicher, doch setzt der Regen wieder ein, geratet ihr mitten in ein Seebeben und müsst ums Wassertreten kämpfen.", "Umgeht ihr dagegen den Rand der Pfütze, findet ihr bald einen anderen Pfad, der zwischen die Bäume oder an den Wänden des House hinaufführt. Während ihr euch hinaufschwitzt, könnt ihr 3 Tage weiterreisen, ohne extremem Wetter zu begegnen. In dieser Höhe seid ihr aber Vogelangriffen ausgesetzt und riskiert ständig abzustürzen."]),
 B("Eichel-Vorrat", ["Einer von euch entfernt sich nur wenige Schritte von den anderen und stolpert über ein Versteck voller Eicheln, die Eichhörnchen für den kommenden Winter horten.", "Betretet ihr es, bekommt ihr so viel Essen, wie ihr tragen könnt, müsst aber aufpassen: Bewegt ihr die falsche Eichel, könntet ihr einen unkontrollierten, plötzlichen Einsturz auslösen und unerwünschte Aufmerksamkeit erregen. Geht ihr dagegen weiter, merkt ihr bald, dass das ganze Gebiet von Eichhörnchen wimmelt, die vergessen haben, wo sie ihre Eicheln versteckten, und unablässig suchen."]),
 B("Hungriger Colossus", ["Euer Reisetag verlief überraschend ruhig, ohne seltsame Ereignisse oder Schwierigkeiten, als ihr plötzlich ein Geräusch hört, das euch das Blut in den Adern gefrieren lässt. Eine kolossale Bestie stapft durch den Garten und versucht verzweifelt, ihren Bauch zu füllen, bevor die Winterkälte einsetzt.", "Ihr müsst wählen, ob ihr euch mit der Umgebung als Deckung vorbeischleichen wollt oder verzweifelt Widerstand leistet. Alternativ geht ihr den Weg zurück und nehmt den langen Weg zum Ziel. Ihr seid nicht in Gefahr, aber die Reise wird um 3 Tage länger."]),
 B("Perfekte Waffe", ["Ein älterer Handwerker und sein junger Sohn haben eine außergewöhnliche Waffe geschmiedet und bringen sie nun dem Adligen, der sie bestellt hat. Zufällig reisen die beiden in eure Richtung und fragen, ob sie den Weg teilen dürfen. Am Ziel erweist sich der Adlige als böser, feindseliger Littling, der sich weigert, den vereinbarten Preis zu zahlen, und sogar den Sohn bedroht.", "Gelingt euch die schwierige Aufgabe, zwischen ihnen zu vermitteln, erntet ihr die Gunst des Adligen, der euch eine Kutsche zur nächsten Stadt erlaubt. Kämpft ihr dagegen, um den Handwerker und seinen Sohn zu schützen, macht ihr euch einen gefährlichen Feind, werdet aber mit der Waffe belohnt. Oder ihr kümmert euch um eure Angelegenheiten und lasst die beiden die Sache untereinander regeln."])
]}
);
})();
